  `municipio_id` bigint(20) unsigned DEFAULT NULL,
  `licencia_id` bigint(20) unsigned DEFAULT NULL,
  `dangerous` tinyint(1) DEFAULT 0,
  `dangerous_note` varchar(255) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `extras` varchar(200) DEFAULT NULL,
  `allergies` varchar(255) DEFAULT NULL,
  `archived_at` timestamp NULL DEFAULT NULL,
  `organisation_id` bigint(20) unsigned DEFAULT NULL,
  `archived_note` varchar(255) DEFAULT NULL,
  `archived_by` int(10) unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `usuario_id` bigint(20) unsigned DEFAULT NULL,
  `current_latitude` decimal(10,7) DEFAULT NULL,
  `current_longitude` decimal(10,7) DEFAULT NULL,
  `last_location_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `taxis_tracking_uuid_unique` (`tracking_uuid`),
