  KEY `municipio_id` (`municipio_id`),
  KEY `type_id` (`tipos`),
  KEY `organisation_id` (`organisation_id`),
  KEY `taxis_taxista_id_index` (`taxista_id`),
  CONSTRAINT `taxis_ibfk_2` FOREIGN KEY (`licencia_id`) REFERENCES `licencias` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `taxis_ibfk_3` FOREIGN KEY (`municipio_id`) REFERENCES `municipios` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `taxis_ibfk_5` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=238 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

